  1→package transcript
  2→
  3→import (
  4→	"bufio"
  5→	"bytes"
  6→	"encoding/json"
  7→	"io"
  8→)
  9→
 10→// droppedTypes are entry types that carry no parser-relevant data.
 11→var droppedTypes = map[string]bool{
 12→	"progress":              true,
 13→	"file-history-snapshot": true,
 14→	"queue-operation":       true,
 15→	"system":                true,
 16→}
 17→
 18→// CompactOptions provides metadata fields written to every output line.
 19→type CompactOptions struct {
 20→	Agent      string // e.g. "claude-code"
 21→	CLIVersion string // e.g. "0.42.0"
 22→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 23→}
 24→
 25→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 26→//
 27→// The output format puts version, agent, and cli_version on every line,
 28→// flattens the message wrapper, and splits user tool results into separate entries:
 29→//
 30→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 31→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 32→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 33→func Compact(content []byte, opts CompactOptions) ([]byte, error) {
 34→	truncated := SliceFromLine(content, opts.StartLine)
 35→	if truncated == nil {
 36→		truncated = []byte{}
 37→	}
 38→
 39→	reader := bufio.NewReader(bytes.NewReader(truncated))
 40→	var result []byte
 41→
 42→	for {
 43→		lineBytes, err := reader.ReadBytes('\n')
 44→		if err != nil && err != io.EOF {
 45→			return nil, err
 46→		}
 47→
 48→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 49→			outputLines := convertLine(lineBytes, opts)
 50→			for _, ol := range outputLines {
 51→				result = append(result, ol...)
 52→				result = append(result, '\n')
 53→			}
 54→		}
 55→
 56→		if err == io.EOF {
 57→			break
 58→		}
 59→	}
 60→
 61→	return result, nil
 62→}
 63→
 64→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
 65→// A user entry with tool_result blocks produces multiple output lines.
 66→func convertLine(lineBytes []byte, opts CompactOptions) [][]byte {
 67→	var raw map[string]json.RawMessage
 68→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
 69→		return nil
 70→	}
 71→
 72→	entryType := unquote(raw["type"])
 73→	if droppedTypes[entryType] {
 74→		return nil
 75→	}
 76→
 77→	switch entryType {
 78→	case "assistant":
 79→		return convertAssistant(raw, opts)
 80→	case "user":
 81→		return convertUser(raw, opts)
 82→	default:
 83→		return nil // drop unknown types in the new format
 84→	}
 85→}
 86→
 87→func convertAssistant(raw map[string]json.RawMessage, opts CompactOptions) [][]byte {
 88→	// Hoist id and content from message to top level
 89→	var id, content json.RawMessage
 90→	if msgRaw, ok := raw["message"]; ok {
 91→		var msg map[string]json.RawMessage
 92→		if json.Unmarshal(msgRaw, &msg) == nil {
 93→			id = msg["id"]
 94→			if contentRaw, ok := msg["content"]; ok {
 95→				content = stripAssistantContent(contentRaw)
 96→			}
 97→		}
 98→	}
 99→
100→	b := marshalOrdered(
101→		"v", mustMarshal(1),
102→		"agent", mustMarshal(opts.Agent),
103→		"cli_version", mustMarshal(opts.CLIVersion),
104→		"type", mustMarshal("assistant"),
105→		"ts", raw["timestamp"],
106→		"id", id,
107→		"content", content,
108→	)
109→	if b == nil {
110→		return nil
111→	}
112→	return [][]byte{b}
113→}
114→
115→func convertUser(raw map[string]json.RawMessage, opts CompactOptions) [][]byte {
116→	var lines [][]byte
117→	ts := raw["timestamp"]
118→
119→	// Parse message content to separate text from tool_results
120→	var textContent string
121→	var toolResults []toolResultEntry
122→
123→	if msgRaw, ok := raw["message"]; ok {
124→		var msg map[string]json.RawMessage
125→		if json.Unmarshal(msgRaw, &msg) == nil {
126→			if contentRaw, ok := msg["content"]; ok {
127→				textContent, toolResults = extractUserContent(contentRaw)
128→			}
129→		}
130→	}
131→
132→	// Emit the user text entry
133→	b := marshalOrdered(
134→		"v", mustMarshal(1),
135→		"agent", mustMarshal(opts.Agent),
136→		"cli_version", mustMarshal(opts.CLIVersion),
137→		"type", mustMarshal("user"),
138→		"ts", ts,
139→		"content", mustMarshal(textContent),
140→	)
141→	if b != nil {
142→		lines = append(lines, b)
143→	}
144→
145→	// Emit separate user_tool_result entries.
146→	//
147→	// Note: full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
148→	// When there are multiple tool_result blocks, each user_tool_result line gets the same
149→	// minimized result. This is a known limitation of the source format — per-tool-use-id
150→	// result data is not available.
151→	var minimizedResult json.RawMessage
152→	if turRaw, ok := raw["toolUseResult"]; ok {
153→		minimizedResult = minimizeToolUseResult(turRaw)
154→	}
155→
156→	for _, tr := range toolResults {
157→		result := minimizedResult
158→		if result == nil {
159→			result = mustMarshal(map[string]interface{}{})
160→		}
161→
162→		b := marshalOrdered(
163→			"v", mustMarshal(1),
164→			"agent", mustMarshal(opts.Agent),
165→			"cli_version", mustMarshal(opts.CLIVersion),
166→			"type", mustMarshal("user_tool_result"),
167→			"ts", ts,
168→			"tool_use_id", mustMarshal(tr.toolUseID),
169→			"result", result,
170→		)
171→		if b != nil {
172→			lines = append(lines, b)
173→		}
174→	}
175→
176→	return lines
177→}
178→
179→type toolResultEntry struct {
180→	toolUseID string
181→}
182→
183→// extractUserContent separates user message content into text and tool_result entries.
184→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
185→	// String content
186→	var str string
187→	if json.Unmarshal(contentRaw, &str) == nil {
188→		return str, nil
189→	}
190→
191→	// Array content
192→	var blocks []map[string]json.RawMessage
193→	if json.Unmarshal(contentRaw, &blocks) != nil {
194→		return "", nil
195→	}
196→
197→	var texts []string
198→	var toolResults []toolResultEntry
199→
200→	for _, block := range blocks {
201→		blockType := unquote(block["type"])
202→
203→		if blockType == "tool_result" {
204→			toolResults = append(toolResults, toolResultEntry{
205→				toolUseID: unquote(block["tool_use_id"]),
206→			})
207→			continue
208→		}
209→
210→		if blockType == "text" {
211→			texts = append(texts, unquote(block["text"]))
212→		}
213→	}
214→
215→	text := ""
216→	if len(texts) > 0 {
217→		text = texts[0]
218→		for i := 1; i < len(texts); i++ {
219→			text += "\n\n" + texts[i]
220→		}
221→	}
222→
223→	return text, toolResults
224→}
225→
226→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
227→	// String content — keep as-is
228→	var str string
229→	if json.Unmarshal(contentRaw, &str) == nil {
230→		return contentRaw
231→	}
232→
233→	// Array of content blocks
234→	var blocks []map[string]json.RawMessage
235→	if json.Unmarshal(contentRaw, &blocks) != nil {
236→		return contentRaw
237→	}
238→
239→	var result []map[string]json.RawMessage
240→	for _, block := range blocks {
241→		blockType := unquote(block["type"])
242→
243→		// Drop thinking blocks
244→		if blockType == "thinking" || blockType == "redacted_thinking" {
245→			continue
246→		}
247→
248→		// Strip tool_use: keep type, id, name, input — drop caller
249→		if blockType == "tool_use" {
250→			stripped := make(map[string]json.RawMessage)
251→			copyField(stripped, block, "type")
252→			copyField(stripped, block, "id")
253→			copyField(stripped, block, "name")
254→			copyField(stripped, block, "input")
255→			result = append(result, stripped)
256→			continue
257→		}
258→
259→		// Other block types (text, image) — keep as-is
260→		result = append(result, block)
261→	}
262→
263→	b, err := json.Marshal(result)
264→	if err != nil {
265→		return contentRaw
266→	}
267→	return b
268→}
269→
270→// minimizeToolUseResult strips a toolUseResult to only the fields the API needs.
271→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
272→	var obj map[string]json.RawMessage
273→	if json.Unmarshal(raw, &obj) != nil {
274→		return raw
275→	}
276→
277→	return marshalOrdered(
278→		"type", obj["type"],
279→		"file", obj["file"],
280→		"error", obj["error"],
281→		"answers", obj["answers"],
282→	)
283→}
284→
285→// marshalOrdered produces a JSON object with keys in the given order.
286→// Pairs with nil values are omitted.
287→func marshalOrdered(pairs ...interface{}) []byte {
288→	var buf bytes.Buffer
289→	buf.WriteByte('{')
290→	first := true
291→	for i := 0; i < len(pairs)-1; i += 2 {
292→		key := pairs[i].(string)
293→		val, _ := pairs[i+1].(json.RawMessage)
294→		if val == nil {
295→			continue
296→		}
297→		if !first {
298→			buf.WriteByte(',')
299→		}
300→		keyJSON, _ := json.Marshal(key)
301→		buf.Write(keyJSON)
302→		buf.WriteByte(':')
303→		buf.Write(val)
304→		first = false
305→	}
306→	buf.WriteByte('}')
307→	return buf.Bytes()
308→}
309→
310→func mustMarshal(v interface{}) json.RawMessage {
311→	b, _ := json.Marshal(v)
312→	return b
313→}
314→
315→func copyField(dst, src map[string]json.RawMessage, key string) {
316→	if v, ok := src[key]; ok {
317→		dst[key] = v
318→	}
319→}
320→
321→func unquote(raw json.RawMessage) string {
322→	var s string
323→	if json.Unmarshal(raw, &s) == nil {
324→		return s
325→	}
326→	return ""
327→}
