135→+	merged := make(map[string]json.RawMessage, len(inner)+2)
136→+	// Copy outer timestamp if present.
137→+	if v, has := raw["timestamp"]; has {
138→+		merged["timestamp"] = v
139→+	}
140→+	// Copy outer id as fallback.
141→+	if v, has := raw["id"]; has {
142→+		merged["id"] = v
