277→+// extractUserContent separates user message content into text and tool_result entries.
278→+// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
279→+func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
280→+	// String content
281→+	var str string
282→+	if json.Unmarshal(contentRaw, &str) == nil {
283→+		return textutil.StripIDEContextTags(str), nil
284→+	}
285→+
286→+	// Array content
287→+	var blocks []map[string]json.RawMessage
288→+	if json.Unmarshal(contentRaw, &blocks) != nil {
289→+		return "", nil
290→+	}
291→+
292→+	var texts []string
293→+	var toolResults []toolResultEntry
294→+
295→+	for _, block := range blocks {
296→+		blockType := unquote(block["type"])
297→+
298→+		if blockType == "tool_result" {
299→+			toolResults = append(toolResults, toolResultEntry{
300→+				toolUseID: unquote(block["tool_use_id"]),
301→+			})
302→+			continue
303→+		}
304→+
305→+		if blockType == "text" {
306→+			stripped := textutil.StripIDEContextTags(unquote(block["text"]))
307→+			if stripped != "" {
308→+				texts = append(texts, stripped)
309→+			}
310→+		}
311→+	}
312→+
313→+	text := ""
314→+	if len(texts) > 0 {
315→+		text = texts[0]
316→+		var sb strings.Builder
317→+		for i := 1; i < len(texts); i++ {
318→+			sb.WriteString("\n\n" + texts[i])
319→+		}
320→+		text += sb.String()
321→+	}
322→+
323→+	return text, toolResults
324→+}
