326→+func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
327→+	// String content — keep as-is
328→+	var str string
329→+	if json.Unmarshal(contentRaw, &str) == nil {
330→+		return contentRaw
331→+	}
332→+
333→+	// Array of content blocks
334→+	var blocks []map[string]json.RawMessage
335→+	if json.Unmarshal(contentRaw, &blocks) != nil {
336→+		return contentRaw
337→+	}
338→+
339→+	var result []map[string]json.RawMessage
340→+	for _, block := range blocks {
341→+		blockType := unquote(block["type"])
342→+
343→+		// Drop thinking blocks
344→+		if blockType == "thinking" || blockType == "redacted_thinking" {
345→+			continue
346→+		}
347→+
348→+		// Strip tool_use: keep type, id, name, input — drop caller
349→+		if blockType == "tool_use" {
