359→+		// Other block types (text, image) — keep as-is
360→+		result = append(result, block)
361→+	}
362→+
363→+	b, err := json.Marshal(result)
364→+	if err != nil {
365→+		return contentRaw
366→+	}
367→+	return b
368→+}
