385→+// marshalOrdered produces a JSON object with keys in the given order.
386→+// Pairs with nil values are omitted.
387→+func marshalOrdered(pairs ...interface{}) []byte {
388→+	var buf bytes.Buffer
389→+	buf.WriteByte('{')
390→+	first := true
391→+	for i := 0; i < len(pairs)-1; i += 2 {
392→+		key := pairs[i].(string)
393→+		val, _ := pairs[i+1].(json.RawMessage)
394→+		if val == nil {
395→+			continue
396→+		}
397→+		if !first {
398→+			buf.WriteByte(',')
399→+		}
400→+		keyJSON, _ := json.Marshal(key)
401→+		buf.Write(keyJSON)
402→+		buf.WriteByte(':')
403→+		buf.Write(val)
404→+		first = false
405→+	}
406→+	buf.WriteByte('}')
407→+	return buf.Bytes()
408→+}
